public int findLargestSubstring(List<String> strings) {
    // We'll use a HashMap to keep track of the longest string and its inverse
    Map<String, Integer> longest = new HashMap<>();

    // Loop through each string in the list
    for (String str : strings) {
        // Find the longest substring that's a palindrome
        int len = str.length();
        for (int i = 0; i < len; i++) {
            // Check if the substring is a palindrome
            if (isPalindrome(str.substring(i, len))) {
                // If it is, add it to the HashMap
                longest.put(str.substring(i, len), len);
                break;
            }
        }
    }

    // Return the length of the longest palindromic substring
    return longest.size();
}

