    // Mark the starting n-tersection as visited
    visited[start[0]][start[1]] = true;

    // Perform BFS to explore the n-teresting space
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);
    while (!queue.isEmpty()) {
        int[] current = queue.remove();
        for (int i = 0; i < n; i++) {
            if (paths[current[0]][i] != 0 && !visited[i][current[1]]) {
                visited[i][current[1]] = true;
