public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {

  // Check if the starting and ending n-tersections are valid
  if (start == null || end == null || start.length != n || end.length != n) {
    return "cannot be travelled";
  }

  // Initialize the visited array to keep track of which n-tersections have been visited
  boolean[][] visited = new boolean[n][n];
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      visited[i][j] = false;
    }
  }

  // Perform a breadth-first search starting from the starting n-tersection
  Queue<Integer> queue = new LinkedList<>();
  queue.add(start[0]);
  queue.add(start[1]);
  visited[start[0]][start[1]] = true;

  while (!queue.isEmpty()) {
    int currentX = queue.remove();
    int currentY = queue.remove();

    // Check if the current n-tersection is the ending n-tersection
    if (currentX == end[0] && currentY == end[1]) {
      return "can be travelled";
    }

    // Check if there are any available paths from the current n-tersection
    for (int[] path : paths) {
      if (path[0] == currentX && path[1] == currentY && !visited[path[2]][path[3]]) {
        // Mark the visited array and add the next n-tersection to the queue
        visited[path[2]][path[3]] = true;
        queue.add(path[2]);
        queue.add(path[3]);
      }
    }
  }

  // If the ending n-tersection was not reachable, return "cannot be travelled"
