public static String convertDatesToWeekdays(String date) {
    // Check if the input date is in the correct format
    if (!date.matches("\\d{2} \\d{2} \\d{4}")) {
        throw new IllegalArgumentException("Invalid date format");
    }

    // Parse the date into a LocalDate object
    LocalDate localDate = LocalDate.parse(date, DateTimeFormatter.ofPattern("MM dd yyyy"));

    // Convert the LocalDate to a WeekDay object
    WeekDay weekDay = WeekDay.of(localDate);

    // Return the weekday of the date in the requested format
    return weekDay.name + " " + localDate.toString();
}

public static String convertDatesToWeekdays(String date) {
    // Validate input
    if (date == null || !date.matches("\\d+ [a-zA-Z]{3} \\d{4}")) {
        throw new IllegalArgumentException("Invalid date format");
    }

    // Extract day, month, and year from input string
    String[] dateParts = date.split(" ");
    int d = Integer.parseInt(dateParts[0]);
    int m = Integer.parseInt(dateParts[1].substring(0, 3));
    int y = Integer.parseInt(dateParts[2]);

    // Create Calendar object with the given date
    Calendar cal = Calendar.getInstance();
    cal.set(y, m, d, 0, 0, 0);

    // Get the day of the week and convert to string
    int dayOfWeek = cal.get(Calendar.DAY_OF_WEEK);
    String weekday = "";
    switch (dayOfWeek) {
        case Calendar.SUNDAY:
            weekday = "Sunday";
            break;
        case Calendar.MONDAY:
            weekday = "Monday";
            break;
        case Calendar.TUESDAY:
            weekday = "Tuesday";
            break;
        case Calendar.WEDNESDAY:
            weekday = "Wednesday";
            break;
        case Calendar.THURSDAY:
            weekday = "Thursday";
            break;
        case Calendar.FRIDAY:
            weekday = "Friday";
            break;
        case Calendar.SATURDAY:
            weekday = "Saturday";
            break;
    }

    // Return the weekday
    return weekday;
}

