    int pivotIndex = findPivotIndex(nums);

    // Perform a binary search on the left and right subarrays
    int leftIndex = 0;
    int rightIndex = nums.length - 1;
    while (leftIndex <= rightIndex) {
        int midIndex = (leftIndex + rightIndex) / 2;
