public double trimMean(int[] arr) {
    // Calculate the mean of the input array
    double mean = 0.0;
    for (int i = 0; i < arr.length; i++) {
        mean += arr[i];
    }
    mean /= arr.length;

    // Calculate the trimmed mean by removing the smallest and largest 5% of the elements
    double trimmedMean = 0.0;
    int numElementsToRemove = (int) (arr.length * 0.05);
    int[] sortedArr = Arrays.stream(arr).sorted().toArray();
    for (int i = numElementsToRemove; i < arr.length - numElementsToRemove; i++) {
        trimmedMean += sortedArr[i];
    }
    trimmedMean /= (arr.length - 2 * numElementsToRemove);

    // Return the trimmed mean with an error within 10^-5
    return Math.round(trimmedMean * 1e5) / 1e5;
}

public double trimMean(int[] arr) {
    double mean = 0;
    int n = arr.length;

    // Sort the array in ascending order
    Arrays.sort(arr);

    // Calculate the 5% quantile of the smallest values
    int smallest5 = (int) Math.round(0.05 * n);

    // Calculate the 5% quantile of the largest values
    int largest5 = (int) Math.round(0.95 * n);

    // Calculate the trimmed mean
    for (int i = smallest5; i < largest5; i++) {
        mean += arr[i];
    }
    mean /= (largest5 - smallest5);

    return mean;
}

