    int n = arr.length;

    if (n < 10) {
        throw new IllegalArgumentException("The array must have at least 10 elements");
    }

    int[] sorted = Arrays.copyOf(arr, n);
    Arrays.sort(sorted);

    int low = (int) Math.round(n * 0.05);
    int high = (int) Math.round(n * 0.95);

    mean = 0;
    for (int i = low; i < high; i++) {
        mean += sorted[i];
    }

    mean /= (high - low);

    return mean;
}

public double trimMean(int[] arr) {
    // Calculate the mean of the remaining elements after removing the smallest 5% and largest 5% of the elements
    // Return the mean with an error within 10^-5

    // Step 1: Calculate the total size of the array
    int totalSize = arr.length;

    // Step 2: Calculate the 5% threshold
    int threshold = (int)Math.ceil(totalSize * 0.05);

    // Step 3: Sort the array in ascending order
    Arrays.sort(arr);

    // Step 4: Calculate the sum of the remaining elements
    double sum = 0;
    for (int i = threshold; i < totalSize - threshold; i++) {
        sum += arr[i];
    }

    // Step 5: Calculate the mean
    double mean = sum / (totalSize - 2 * threshold);

    // Step 6: Return the mean with an error within 10^-5
    return Math.round(mean * 100000) / 100000;
}

public double trimMean(int[] arr) {
    // Step 1: Calculate the mean of the input array
    double mean = Arrays.stream(arr).average().orElse(0.0);

    // Step 2: Sort the array in ascending order
    Arrays.sort(arr);

    // Step 3: Calculate the starting and ending indexes of the 5% trim region
    int startIdx = (int) Math.floor(0.05 * arr.length);
    int endIdx = (int) Math.ceil(0.95 * arr.length);

    // Step 4: Calculate the mean of the remaining elements
    double trimMean = Arrays.stream(arr, startIdx, endIdx).average().orElse(0.0);

    // Step 5: Return the trimmed mean
    return trimMean;
}

