public String sortString(String s) {
    if (s == null || s.length() == 0) {
        return s;
    }

    List<Character> sorted = new ArrayList<>();
    while (sorted.size() < s.length()) {
        char smallest = '\uFFFF';
        char largest = '\0';
        for (char c : s.toCharArray()) {
            if (c < smallest) {
                smallest = c;
            }
            if (c > largest) {
                largest = c;
            }
        }
        sorted.add(smallest);
        sorted.add(largest);
        s = s.replaceFirst("" + smallest, "");
        s = s.replaceFirst("" + largest, "");
    }
    StringBuilder result = new StringBuilder();
    for (char c : sorted) {
        result.append(c);
    }
    return result.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    StringBuilder result = new StringBuilder();
    char smallestChar = s.charAt(0);
    char largestChar = s.charAt(s.length() - 1);
    result.append(smallestChar);
    int lastInsertedIndex = 1;

    while (result.length() < s.length()) {
        char nextChar = (char) (smallestChar + 1);
        int nextCharIndex = s.indexOf(nextChar, lastInsertedIndex);
        if (nextCharIndex == -1) {
            nextChar = s.charAt(s.length() - 1);
        }
        result.append(nextChar);
        lastInsertedIndex = nextCharIndex + 1;
    }

    if (result.charAt(result.length() - 1) != largestChar) {
        result.append(largestChar);
    }

    return result.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    char[] sortedChars = s.toCharArray();
    Arrays.sort(sortedChars);

    StringBuilder sortedString = new StringBuilder();
    for (int i = 0; i < sortedChars.length; i++) {
        if (i % 2 == 0) {
            sortedString.append(sortedChars[i]);
        } else {
            sortedString.append(sortedChars[sortedChars.length - i - 1]);
        }
    }
    return sortedString.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }

    // step 1: pick the smallest character and append it to the result
    char smallest = s.charAt(0);
    String result = String.valueOf(smallest);

    // step 2: pick the smallest character which is greater than the last appended character and append it
    for (int i = 1; i < s.length(); i++) {
        char current = s.charAt(i);
        if (current > smallest) {
            result += current;
            smallest = current;
        }
    }

    // step 3: repeat step 2 until you cannot pick more characters
    while (result.length() < s.length()) {
        smallest = s.charAt(result.length());
        result += smallest;
    }

    // step 4: pick the largest character and append it to the result
    char largest = s.charAt(s.length() - 1);
    result += largest;

    // step 5: pick the largest character which is smaller than the last appended character and append it
    for (int i = s.length() - 2; i >= 0; i--) {
        if (s.charAt(i) < largest) {
            result += s.charAt(i);
            largest = s.charAt(i);
        }
    }

    // step 6: repeat step 5 until you cannot pick more characters
    while (result.length() < s.length()) {
        largest = s.charAt(s.length() - result.length() - 1);
        result += largest;
    }

    return result;
}

public String sortString(String s) {
  // Step 1: Sort the characters in the string in ascending order
  char[] chars = s.toCharArray();
  Arrays.sort(chars);

  // Step 2: Re-order the characters according to the algorithm
  String result = "";
  while (chars.length > 0) {
    // Step 2.1: Pick the smallest character and append it to the result
    result += chars[0];
    chars = Arrays.copyOfRange(chars, 1, chars.length);

    // Step 2.2: Pick the smallest character which is greater than the last appended character and append it
    int minIndex = 0;
    for (int i = 0; i < chars.length; i++) {
      if (chars[i] > result.charAt(result.length() - 1)) {
        minIndex = i;
        break;
      }
    }
    result += chars[minIndex];
    chars = Arrays.copyOfRange(chars, 0, minIndex) + Arrays.copyOfRange(chars, minIndex + 1, chars.length);

    // Step 2.3: Repeat step 2.1 and 2.2 until you cannot pick more characters
    while (chars.length > 0 && chars[0] <= result.charAt(result.length() - 1)) {
      result += chars[0];
      chars = Arrays.copyOfRange(chars, 1, chars.length);
    }

    // Step 3: Pick the largest character and append it to the result
    result += chars[chars.length - 1];
    chars = Arrays.copyOfRange(chars, 0, chars.length - 1);

    // Step 4: Pick the largest character which is smaller than the last appended character and append it
    int maxIndex = chars.length - 1;
    for (int i = chars.length - 1; i >= 0; i--) {
      if (chars[i] < result.charAt(result.length() - 1)) {
        maxIndex = i;
        break;
      }
    }
    result += chars[maxIndex];
    chars = Arrays.copyOfRange(chars, 0, maxIndex) + Arrays.copyOfRange(chars, maxIndex + 1, chars.length);

    // Step 4.3: Repeat step 4.1 and 4.2 until you cannot pick more characters
    while (chars.length > 0 && chars[chars.length - 1] >= result.charAt(result.length() - 1)) {
      result += chars[chars.length - 1];
      chars = Arrays.copyOfRange(chars, 0, chars.length - 1);
    }
  }

  return result;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums.length <= 1) {
        return false;
    }

    int totalSum = 0;
    for (int i = 0; i < nums.length; i++) {
        totalSum += nums[i];
    }

    int average = totalSum / nums.length;

    int leftSum = 0;
    for (int i = 0; i < nums.length / 2; i++) {
        leftSum += nums[i];
    }

    int rightSum = totalSum - leftSum;

    return leftSum == rightSum;
}

