    }
    int average = sum / nums.length;
    for (int i = 0; i < nums.length; i++) {
        if (i == nums.length - 1) {
            break;
        }
        int avg = sum / (nums.length - i - 1);
        if (avg == average) {
            return true;
        }
    }
    return false;
}

