public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 2], dp[i - 2] + cost[i - 1]);
    }
    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
  if (cost == null || cost.length == 0) {
    return 0;
  }

  // Initialize variables
  int minCost = 0;
  int currentCost = 0;
  int previousCost = 0;
  int currentIndex = 0;

  while (currentIndex < cost.length) {
    currentCost = cost[currentIndex];
    if (currentIndex == 0) {
      // If starting from index 0, set the initial previous cost to 0
      previousCost = 0;
    } else {
      previousCost = cost[currentIndex - 1];
    }

    // Calculate the minimum cost to reach the current index
    minCost = Math.min(previousCost + currentCost, minCost + currentCost);
    currentIndex++;
  }

  return minCost;
}

