public boolean hasAllCodes(String s, int k) {
    // Step 1: Check if the input string is valid
    if (s == null || s.length() < k) {
        return false;
    }

    // Step 2: Create a set to store the substrings of length k
    Set<String> substrings = new HashSet<>();

    // Step 3: Iterate through the input string and add every substring of length k to the set
    for (int i = 0; i <= s.length() - k; i++) {
        substrings.add(s.substring(i, i + k));
    }

    // Step 4: Check if the set contains all binary strings of length k
    for (int i = 0; i < (1 << k); i++) {
        String binaryString = Integer.toBinaryString(i);
        if (!substrings.contains(binaryString)) {
            return false;
        }
    }

    return true;
}

