public int minInsertions(String s) {
    // Step 1: Validate the input string
    if (s == null || s.isEmpty()) {
        return 0;
    }

    // Step 2: Count the number of '(' and ')' in the input string
    int numLeftParens = 0;
    int numRightParens = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            numLeftParens++;
        } else if (c == ')') {
            numRightParens++;
        }
    }

    // Step 3: Calculate the minimum number of insertions required to make the string balanced
    int minInsertions = Math.abs(numLeftParens - numRightParens);

    return minInsertions;
}

