public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int minOperations = 0;
    while (arr[0] != arr[n - 1]) {
        int diff = Math.abs(arr[0] - arr[n - 1]);
        arr[0] -= diff;
        arr[n - 1] += diff;
        minOperations++;
    }

    return minOperations;
}

