public int findMinFibonacciNumbers(int k) {
  // Initialize a list to store the Fibonacci numbers
  List<Integer> fibList = new ArrayList<>();

  // Add the first two Fibonacci numbers to the list
  fibList.add(1);
  fibList.add(1);

  // Loop until we have found a solution
  while (true) {
    // Get the last two Fibonacci numbers from the list
    int fn = fibList.get(fibList.size() - 1);
    int fn1 = fibList.get(fibList.size() - 2);

    // Calculate the sum of the last two Fibonacci numbers
    int sum = fn + fn1;

    // If the sum is equal to k, return the number of Fibonacci numbers in the list
    if (sum == k) {
      return fibList.size();
    }

    // If the sum is greater than k, remove the last Fibonacci number from the list
    if (sum > k) {
      fibList.remove(fibList.size() - 1);
      continue;
    }

    // Otherwise, add the next Fibonacci number to the list
    fibList.add(sum);
  }
}

public int findMinFibonacciNumbers(int k) {
