    // the same as the probability that the first passenger will sit in their own seat,
    // which is 1/n.
    return 1.0 / n;
}

public static double calculateProbability(int n) {
    // Special case: If only one passenger, return 1.0
    if (n == 1) {
        return 1.0;
    }

    // Initialize variables
    double probability = 0.0;
    int lastSeat = n;

    // Loop through each passenger and calculate the probability of each one sitting in their own seat
    for (int i = 1; i <= n; i++) {
        // If the current passenger is not the last passenger, calculate the probability of them sitting in their own seat
        if (i != lastSeat) {
            probability += 1.0 / n;
        }
    }

    return probability;
}

