public static double calculateProbability(int n) {
    // Calculate the probability that the last passenger will sit in their own seat.
    // Passengers are assigned seats randomly.

    // Handle invalid inputs.
    if (n < 1) {
        throw new IllegalArgumentException("n must be a positive integer.");
    }

    // Calculate the number of permutations.
    BigInteger permutations = BigInteger.valueOf(1);
    for (int i = 1; i <= n; i++) {
        permutations = permutations.multiply(BigInteger.valueOf(i));
    }

    // Calculate the number of derangements.
    BigInteger derangements = BigInteger.valueOf(1);
    for (int i = 1; i <= n - 1; i++) {
        derangements = derangements.multiply(BigInteger.valueOf(i));
        derangements = derangements.add(BigInteger.valueOf(1));
    }

    // Calculate the probability.
    double probability = ((double) derangements.longValue()) / permutations.longValue();

    // Return the probability.
    return probability;
}

public static double calculateProbability(int n) {
    // Step 1: Calculate the total number of possible seat assignments
    int totalAssignments = 1;
    for (int i = 1; i <= n; i++) {
        totalAssignments *= i;
    }

    // Step 2: Calculate the number of favorable seat assignments, i.e., the ones where the last passenger sits in their own seat
    int favorableAssignments = 1;
    for (int i = 1; i <= n - 1; i++) {
        favorableAssignments *= i;
    }

    // Step 3: Calculate the probability
    double probability = (double) favorableAssignments / totalAssignments;

    return probability;
}

