public static String addThousandSeparator(int n) {
    // Handle negative numbers
    if (n < 0) {
        String result = "-" + addThousandSeparator(-n);
        return result;
    }

    // Split the number into thousands
    int numThousands = (int) Math.floor(n / 1000);
    int remainder = n % 1000;

    // Add a dot after each thousand
    String result = "";
    for (int i = 0; i < numThousands; i++) {
        result += "." + String.format("%03d", remainder);
        remainder /= 1000;
    }

    // Add the remaining digits
    result += String.format("%03d", remainder);

    return result;
}

