public static int squarePermutations(int[] A) {
    int count = 0;
    List<Integer> squares = new ArrayList<>();

    for (int i = 0; i < A.length; i++) {
        int square = (int) Math.sqrt(A[i] + A[i + 1]);
        if (i == A.length - 1) {
            squares.add(square);
        } else {
            int nextSquare = (int) Math.sqrt(A[i + 1] + A[i + 2]);
            if (square != nextSquare) {
                squares.add(square);
            }
        }
    }

    for (Integer square : squares) {
        int permutation = 1;
        for (int i = 1; i < A.length; i++) {
            int diff = Math.abs(square - A[i]);
            if (diff == 0) {
                permutation = permutation * 2;
            } else if (diff == 1) {
                permutation = permutation * 3;
            }
        }
        count += permutation;
    }

    return count;
}

