}

public static int largestRectangleArea(int[] heights) {
  if (heights.length == 0) {
    return 0;
  }

  int maxArea = 0;
  int[] leftHeights = new int[heights.length];
  int[] rightHeights = new int[heights.length];
  int currentHeight;

  for (int i = 0; i < heights.length; i++) {
    currentHeight = heights[i];
    leftHeights[i] = currentHeight;
    for (int j = i - 1; j >= 0 && currentHeight >= heights[j]; j--) {
      leftHeights[i] = Math.max(leftHeights[i], currentHeight);
      currentHeight = heights[j];
    }

    currentHeight = heights[i];
    rightHeights[i] = currentHeight;
    for (int j = i + 1; j < heights.length && currentHeight >= heights[j]; j++) {
      rightHeights[i] = Math.max(rightHeights[i], currentHeight);
      currentHeight = heights[j];
    }

    maxArea = Math.max(maxArea, (leftHeights[i] + rightHeights[i] - 1) * currentHeight);
  }

  return maxArea;
}

