    // Check if the first and second points are the same
    if (points[0][0] == points[1][0] && points[0][1] == points[1][1]) {
        return false;
    }

    // Check if the third point is on the same side of the line as the first two points
    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];
    int determinant = (x1 - x2) * (y3 - y2) - (x3 - x2) * (y1 - y2);
    if (determinant != 0) {
        return false;
    }

    // Check if the angle between the first and second line segments is less than 180 degrees
    double angle = Math.toDegrees(Math.atan2(x2 - x1, y2 - y1)) - Math.toDegrees(Math.atan2(x3 - x1, y3 - y1));
    if (angle < 0) {
        angle += 360;
    }
    return angle < 180;
}

public static boolean isBoomerang(int[][] points) {
  // Step 1: Check if the input array has exactly 3 points.
  if (points.length != 3) {
    return false;
  }

  // Step 2: Check if the three points form a straight line.
  if (isStraightLine(points[0], points[1], points[2])) {
    return false;
  }

  // Step 3: Check if the first and third points are the same.
  if (points[0][0] == points[2][0] && points[0][1] == points[2][1]) {
    return false;
  }

  // Step 4: Check if the slope of the line segment between the first and second points is equal to the slope of the line segment between the second and third points.
  if (slope(points[0], points[1]) == slope(points[1], points[2])) {
    return false;
  }

  return true;
}

