public static int calculateEnergy(String s) {
        // Initialize the energy to 0
        int energy = 0;

        // Check if the input string is empty
        if (s.isEmpty()) {
            return energy;
        }

        // Split the input string into individual characters
        char[] chars = s.toCharArray();

        // Initialize the longest substring length to 0
        int longestSubstringLength = 0;

        // Loop through each character in the input string
        for (int i = 0; i < chars.length; i++) {
            // Initialize the current substring length to 0
            int currentSubstringLength = 0;

            // Loop through each character in the input string starting from the current character
            for (int j = i; j < chars.length; j++) {
                // Check if the current character is the same as the previous character
                if (chars[j] == chars[j - 1]) {
                    // Increment the current substring length
                    currentSubstringLength++;
                } else {
                    // Check if the current substring length is greater than the longest substring length
                    if (currentSubstringLength > longestSubstringLength) {
                        // Update the longest substring length
                        longestSubstringLength = currentSubstringLength;
                    }

                    // Reset the current substring length
                    currentSubstringLength = 0;
                }
            }

            // Check if the current substring length is greater than the longest substring length
            if (currentSubstringLength > longestSubstringLength) {
                // Update the longest substring length
                longestSubstringLength = currentSubstringLength;
            }
        }

        // Update the energy to the longest substring length
        energy = longestSubstringLength;

        return energy;
    }

