public static int minPerfectSquareSum(int n) {
    int minSquares = Integer.MAX_VALUE;
    int[] perfectSquares = new int[n + 1];
    perfectSquares[0] = 0;
    for (int i = 1; i <= n; i++) {
        perfectSquares[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            if (perfectSquares[i - j * j] != Integer.MAX_VALUE) {
                perfectSquares[i] = Math.min(perfectSquares[i], perfectSquares[i - j * j] + 1);
            }
        }
        if (perfectSquares[i] != Integer.MAX_VALUE) {
            minSquares = Math.min(minSquares, perfectSquares[i]);
        }
    }
    return minSquares == Integer.MAX_VALUE ? -1 : minSquares;
}

public static int minPerfectSquareSum(int n) {
    if (n == 0) {
        return 0;
    }

    int minSquares = Integer.MAX_VALUE;
    int[] perfectSquares = generatePerfectSquares(n);

    for (int i = 0; i < perfectSquares.length; i++) {
        int squaresSum = perfectSquares[i];
        if (squaresSum == n) {
            return 1;
        } else if (squaresSum > n) {
            break;
        }

        int remaining = n - squaresSum;
        int count = 1 + minPerfectSquareSum(remaining);
        if (count < minSquares) {
            minSquares = count;
        }
    }

    return minSquares;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    while (n > 0) {
        int root = (int) Math.sqrt(n);
        if (root * root == n) {
            count++;
            break;
        }
        n -= root * root;
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    int minSquares = 0;
    while (n > 0) {
        int root = (int) Math.sqrt(n);
        minSquares++;
        n -= root * root;
    }
    return minSquares;
}

public static int minPerfectSquareSum(int n) {
    int min = Integer.MAX_VALUE;
    for (int i = 1; i * i <= n; i++) {
        int count = 0;
        int temp = n;
        while (temp > 0) {
            count++;
            temp -= i * i;
        }
        if (count < min) {
            min = count;
        }
    }
    return min;
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    StringBuilder builder = new StringBuilder();
    String[] words = s.split(" ");
    for (String word : words) {
        builder.append(new StringBuilder(word).reverse().toString());
        builder.append(" ");
    }
    return builder.toString().trim();
}

public static String reverseWords(String s) {
  // Step 1: Split the input string into words
  String[] words = s.split(" ");

  // Step 2: Reverse the characters of each word
  for (int i = 0; i < words.length; i++) {
    char[] wordChars = words[i].toCharArray();
    for (int j = 0; j < wordChars.length / 2; j++) {
      char temp = wordChars[j];
      wordChars[j] = wordChars[wordChars.length - j - 1];
      wordChars[wordChars.length - j - 1] = temp;
    }
    words[i] = new String(wordChars);
  }

  // Step 3: Join the words back into a string
  return String.join(" ", words);
}

